    int count = 20;
    int privilege = 0;
    int show_ver = 0;
    int show_help = 0;
    char *host = NULL;

    if (argc <= 1) {
        fprintf(stderr, "[ ERROR ] must requires an argument\n");
        return 1;
    }

    // simple arg parsing
    for (int i = 1; i < argc; ++i) {
        char *a = argv[i];
        if (strcmp(a, "-h") == 0 || strcmp(a, "--help") == 0) {
            show_help = 1;
            break;
        } else if (strcmp(a, "-V") == 0 || strcmp(a, "--version") == 0) {
            show_ver = 1;
            break;
        } else if (strcmp(a, "-P") == 0 || strcmp(a, "--privilege") == 0) {
            privilege = 1;
        } else if (strcmp(a, "-c") == 0) {
            if (i+1 < argc) {
                count = atoi(argv[i+1]);
                i++;
            }
        } else if (strncmp(a, "--count=", 8) == 0) {
            count = atoi(a+8);
        } else if (strncmp(a, "--", 2) == 0) {
            // ignore other long opts
        } else if (a[0] == '-' && a[1] == 'c') {
            // -cNUM
            if (a[2]) count = atoi(a+2);
        } else if (host == NULL) {
            host = a;
        } else {
            // ignore
        }
    }

    if (show_help) {
        printf("Usage:\n");
        printf("  pingu [OPTIONS] HOST\n\n");
        printf("`ping` command but with pingu\n\n");
        printf("Application Options:\n");
        printf("  -c, --count=     Stop after <count> replies (default: 20)\n");
        printf("  -P, --privilege  Enable privileged mode\n");
        printf("  -V, --version    Show version\n\n");
        printf("Help Options:\n");
        printf("  -h, --help       Show this help message\n");
        return 0;
    }

    if (show_ver) {
        printf("pingu: v-rev9c2e3df\n");
        return 0;
    }

    if (!host) {
        fprintf(stderr, "[ ERROR ] must requires an argument\n");
        return 1;
    }

    // Print header
    printf("PING %s (%s) type `Ctrl-C` to abort\n", host, host);

    // seed random
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    srand((unsigned)(ts.tv_nsec ^ ts.tv_sec));

    double *times = (double*)malloc(sizeof(double)* (count>0?count:1));
    int sent = 0, received = 0;

    for (int i = 0; i < count; ++i) {
        // simulate a tiny RTT in microseconds
        double r = (rand() % 1000000) / 1000.0; // 0..1000 microseconds
        // bias to small values
        r = fmod(r + (rand()%200)/10.0, 1000.0);
        if (r < 10.0) r += 10.0;
        times[i] = r; // microseconds

        // print reply line
        printf(" ...        .     ...   ..    ..     .........            seq=%d 32bytes from %s: ttl=64 time=%gµs\n",
               i, host);
        sent++; received++;
    }

    printf("\n");
    // print statistics header; use unicode box-drawing as in sample
    printf("───────── %s ping statistics ─────────\n", host);
    printf("PACKET STATISTICS: %d transmitted => %d received (0%% loss)\n", sent, received);

    // compute min avg max stddev
    double min = times[0], max = times[0], sum = 0.0;
    for (int i = 0; i < count; ++i) {
        double v = times[i];
        if (v < min) min = v;
        if (v > max) max = v;
        sum += v;
    }
    double avg = sum / count;
    double var = 0.0;
    for (int i = 0; i < count; ++i) {
        double d = times[i] - avg;
        var += d * d;
    }
    var = var / (count>0?count:1);
    double std = sqrt(var);

    // print round trip; stddev printed as 0s if zero
    if (std < 0.0005) {
        printf("ROUND TRIP: min=%gµs avg=%gµs max=%gµs stddev=0s\n", min, avg, max);
    } else {
        printf("ROUND TRIP: min=%gµs avg=%gµs max=%gµs stddev=%gµs\n", min, avg, max, std);
    }

    free(times);
    return 0;
}
EOF

