EOF

chmod +x compile.sh

# update .gitignore to ensure executable not committed
sed -n '1,200p' .gitignore > /dev/null 2>&1 || true
if ! grep -q "^executable$" .gitignore 2>/dev/null; then
  echo "executable" >> .gitignore
fi

# run compile to produce executable
./compile.sh

# run some tests
./executable -h > help.txt || true
./executable -V > ver.txt || true
./executable 127.0.0.1 -c 1 > out.txt || true

 echo "--- HELP ---" && sed -n '1,200p' help.txt
 echo "--- VER ---" && sed -n '1,200p' ver.txt
 echo "--- OUT ---" && sed -n '1,200p' out.txt

# add files and commit
git add pingu.c compile.sh .gitignore
git commit -m "Implement pingu replacement" || true

"}

